var FRONTMATTER = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;
function parseFrontmatter(raw) {
	const match = FRONTMATTER.exec(raw);
	if (!match) return {
		meta: {},
		body: raw
	};
	const meta = {};
	for (const line of (match[1] ?? "").split(/\r?\n/)) {
		const colon = line.indexOf(":");
		if (colon <= 0) continue;
		meta[line.slice(0, colon).trim()] = line.slice(colon + 1).trim();
	}
	return {
		meta,
		body: raw.slice(match[0].length).replace(/\r\n/g, "\n").replace(/^\n+/, "")
	};
}
/** Inline Markdown down to its words: code ticks, emphasis and link targets go. */
function stripInline(text) {
	return text.replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1").replace(/`([^`]*)`/g, "$1").replace(/(\*\*|__)(.*?)\1/g, "$2").replace(/(\*|_)(.*?)\1/g, "$2");
}
/** The anchor for a heading: lowercase, with every run of other characters folded to one hyphen. */
function slugifyHeading(heading) {
	return stripInline(heading).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-+|-+$/g, "");
}
/** Markdown as the plain text a reader would see, one line per block line. */
function stripMarkdown(markdown) {
	return markdown.split("\n").map((line) => stripInline(line.replace(/^\s*>\s?/, "").replace(/^\s*\[!(NOTE|TIP|WARNING)\]\s*$/i, "").replace(/^\s*```.*$/, "").replace(/^\s*\|?(\s*:?-{3,}:?\s*\|?)+\s*$/, "").replace(/^\s*#{1,6}\s+/, "").replace(/^\s*([-*+]|\d+\.)\s+/, "")).replace(/\s*\|\s*/g, " ").trim()).filter(Boolean).join("\n");
}
var HEADING = /^(#{2,3})\s+(.+?)\s*#*\s*$/;
function splitSections(body) {
	const sections = [];
	const used = /* @__PURE__ */ new Map();
	let current = {
		id: "",
		heading: "",
		level: 0,
		markdown: ""
	};
	let lines = [];
	let inFence = false;
	let parent;
	const flush = () => {
		current.markdown = lines.join("\n").trim();
		if (current.level !== 0 || current.markdown) sections.push(current);
	};
	for (const line of body.split("\n")) {
		if (/^\s*(```|~~~)/.test(line)) inFence = !inFence;
		const match = inFence ? null : HEADING.exec(line);
		if (!match) {
			lines.push(line);
			continue;
		}
		flush();
		const level = match[1].length;
		const heading = stripInline(match[2]);
		const base = slugifyHeading(heading);
		const seen = used.get(base) ?? 0;
		used.set(base, seen + 1);
		if (level === 2) parent = heading;
		current = {
			id: seen === 0 ? base : `${base}-${seen}`,
			heading,
			level,
			...level === 3 && parent ? { parent } : {},
			markdown: ""
		};
		lines = [];
	}
	flush();
	return sections;
}
function parseArticle(slug, raw) {
	const { meta, body } = parseFrontmatter(raw);
	if (!meta.title) throw new Error(`Help article ${slug}.md has no title in its header.`);
	const order = Number.parseInt(meta.order ?? "", 10);
	return {
		slug,
		title: meta.title,
		category: meta.category ?? "Getting started",
		order: Number.isFinite(order) ? order : 999,
		summary: meta.summary ?? "",
		keywords: (meta.keywords ?? "").split(",").map((k) => k.trim()).filter(Boolean),
		...meta.route ? { route: meta.route } : {},
		body,
		sections: splitSections(body)
	};
}
